  chooseOutboundIdentity=function(){const session=phoneSession(),ownerName=phoneOwnerName(),operator=actualOperatorName(session);phoneOverlay(`<header><div><small>代发身份</small><h2>本条消息的对外身份</h2></div><button onclick="v454ClosePhoneOverlay()">×</button></header><p class="v454-phone-overlay-note">底层永远记录真实操作者。收件 NPC 只有在语气、关系或记录存在可靠证据时才能怀疑冒充。</p><div class="v454-phone-overlay-list"><button onclick="v454SetOutboundIdentity('phone-owner')"><b>显示为手机主人 · ${E(ownerName)}</b><small>对外只显示手机主人</small></button><button onclick="v454SetOutboundIdentity('operator')"><b>公开实际操作者 · ${E(operator)}</b><small>明确显示由实际操作者发送</small></button></div>`)};
  setOutboundIdentity=function(mode){const session=phoneSession();session.outboundIdentity=mode==='operator'?'operator':'phone-owner';try{v435PhoneSession=session}catch{}closePhoneOverlay();openPhoneThread(activePhoneThreadId)};
  openPhoneMessageMenu=function(messageId){const thread=phoneThread(),message=thread?.messages.find(item=>item.id===messageId);if(!message)return;activePhoneMessageId=messageId;phoneOverlay(`<header><div><small>LOCAL MESSAGE</small><h2>本机消息操作</h2></div><button onclick="v454ClosePhoneOverlay()">×</button></header><p class="v454-phone-overlay-note">旧记录的编辑和修改都只改变当前手机本地副本；真正发送的新消息才同步双方。</p><div class="v454-phone-overlay-list"><button onclick="v454EditPhoneMessage('silent')"><b>静默编辑本机副本</b><small>角色不会凭空知道</small></button><button onclick="v454EditPhoneMessage('plot')"><b>剧情修改本机副本</b><small>写入相关事件记忆</small></button><button onclick="v454OpenPhoneDiff(${A(messageId)})"><b>本机 / 远端差异</b><small>打开独立对比页</small></button><button class="danger" onclick="v454DeleteSinglePhoneMessage(${A(messageId)})"><b>删除本机消息</b><small>选择删除语义后进入回收站</small></button></div>`)};
  editPhoneMessage=function(mode){if(!safePhonePermission('edit'))return toast('本次连接没有修改权限');const message=phoneThread()?.messages.find(item=>item.id===activePhoneMessageId);if(!message)return;phoneOverlay(`<header><div><small>${mode==='plot'?'PLOT MODIFY':'SILENT EDIT'}</small><h2>${mode==='plot'?'剧情修改':'静默编辑'}本机副本</h2></div><button onclick="v454ClosePhoneOverlay()">×</button></header><p class="v454-phone-overlay-note">NPC 远端原始记录不会自动变化。</p><label class="v454-phone-overlay-field"><span>远端原始记录</span><textarea readonly>${E(message.remoteText||message.text||'')}</textarea></label><label class="v454-phone-overlay-field"><span>本机显示内容</span><textarea id="v454PhoneEditText">${E(messageText(message))}</textarea></label>${mode==='plot'?'<label class="v454-phone-overlay-field"><span>剧情修改原因</span><textarea id="v454PhoneEditReason" placeholder="写入相关参与者的手机事件时间线"></textarea></label>':''}<footer><button onclick="v454ClosePhoneOverlay()">取消</button><button class="primary" onclick="v454SavePhoneMessageEdit('${mode}')">保存本机副本</button></footer>`)};
  savePhoneMessageEdit=function(mode){const message=phoneThread()?.messages.find(item=>item.id===activePhoneMessageId),next=document.getElementById('v454PhoneEditText')?.value.trim(),reason=document.getElementById('v454PhoneEditReason')?.value.trim()||'';if(!message||!next)return toast('内容不能为空');if(mode==='plot'&&!reason)return toast('剧情修改需要填写原因');const before=messageText(message);message.editHistory=Array.isArray(message.editHistory)?message.editHistory:[];message.modifyHistory=Array.isArray(message.modifyHistory)?message.modifyHistory:[];if(mode==='plot'){message.modifyHistory.push({before,after:next,reason,at:NOW(),actualActor:actualOperatorName()});message.modifiedAt=NOW()}else{message.editHistory.push({before,after:next,at:NOW(),actualActor:actualOperatorName()});message.editedAt=NOW()}message.localText=next;recordPhoneEvent({phoneOwner:activePhoneOwner,operation:mode==='plot'?'message-plot-modify':'message-silent-edit',localChanged:true,remoteSynced:false,remember:mode==='plot',details:{summary:mode==='plot'?`剧情修改了与${phoneThread()?.title||'联系人'}的本机记录`:'静默编辑本机记录',reason}});save();closePhoneOverlay();openPhoneThread(activePhoneThreadId);toast(mode==='plot'?'剧情修改已保存；远端不变':'本机副本已静默编辑；远端不变')};
  openPhoneDiff=function(messageId){closePhoneOverlay();activePhoneMessageId=messageId;const message=phoneThread()?.messages.find(item=>item.id===messageId);if(!message)return;setPhoneContent(`<div class="vphone v454-messages-shell ${activePhoneOwner==='user'?'is-user':'is-character'}"><section class="v454-phone-page" data-phone-route="message-diff">${phoneHead('本机 / 远端差异',`v454OpenPhoneThread(${A(activePhoneThreadId)})`,'来源',`toast('差异来源与实际操作者已经记录')`)}<main class="v454-phone-body">${phoneIdentityMarkup()}<div class="v454-compare"><article class="changed"><b>本机副本</b><small>${E(messageText(message))}\n\n实际操作者：${E(message.editHistory?.at(-1)?.actualActor||message.modifyHistory?.at(-1)?.actualActor||actualOperatorName())}\n修改时间：${E(message.editedAt||message.modifiedAt||'未修改')}\n世界时间：${E(message.worldTimeText||'')}</small></article><article><b>远端原始记录</b><small>${E(message.remoteText||message.text||'')}\n\n远端没有被本机编辑自动覆盖。</small></article></div><section class="v454-light-panel" style="margin-top:9px"><h3>差异来源</h3><p>${message.modifiedAt?'剧情修改：相关事件会进入记忆。':message.editedAt?'静默编辑：角色不会凭空知道。':'本机与远端当前一致。'}</p><div class="v454-light-actions"><button onclick="v454RestoreLocalFromRemote()">恢复本机为远端</button><button class="dark" onclick="v454OpenPhoneThread(${A(activePhoneThreadId)})">保留本机篡改</button></div></section></main></section></div>`)};
  window.v454ChooseOutboundIdentity=chooseOutboundIdentity;window.v454SetOutboundIdentity=setOutboundIdentity;window.v454OpenPhoneMessageMenu=openPhoneMessageMenu;window.v454EditPhoneMessage=editPhoneMessage;window.v454SavePhoneMessageEdit=savePhoneMessageEdit;window.v454OpenPhoneDiff=openPhoneDiff;

  function openPhoneTools(){setPhoneContent(`<div class="vphone v454-messages-shell ${activePhoneOwner==='user'?'is-user':'is-character'}"><section class="v454-phone-page" data-phone-route="phone-tools">${phoneHead('手机管理中心','v454OpenPhoneMessages()','桌面',`v43PhoneDesktop(${A(activePhoneOwner)})`)}<main class="v454-phone-body">${phoneIdentityMarkup()}<div class="v454-phone-tools">${phoneTool('联','联系人白名单','世界绑定对象、当前面具关系、正式角色 / MPC 与已有群聊','v454OpenPhoneContacts()')}${phoneTool('差','本机 / 远端差异','查看旧记录的本机副本与远端原始记录',activePhoneThreadId?`v454OpenPhoneThread(${A(activePhoneThreadId)})`:`toast('请先进入一条会话')`)}${phoneTool('删','删除与回收站','单条、多选、清应用、整机重置与恢复','v454OpenPhoneMessageManager()')}${phoneTool('AI','实时回应调用','省调用模式或高拟真双请求','v454OpenPhoneSettings()')}</div></main></section></div>`)}
  function phoneTool(icon,title,copy,action){return`<button class="v454-phone-tool" onclick="${action}"><span>${E(icon)}</span><span><b>${E(title)}</b><small>${E(copy)}</small></span><i>›</i></button>`}
  function openPhoneMessageManager(){const thread=phoneThread(),rows=thread?.messages||[];phoneSelectedIds=new Set();setPhoneContent(`<div class="vphone v454-messages-shell ${activePhoneOwner==='user'?'is-user':'is-character'}"><section class="v454-phone-page" data-phone-route="message-manager">${phoneHead('聊天记录管理',thread?`v454OpenPhoneThread(${A(thread.id)})`:'v454OpenPhoneTools()','回收站','v454OpenPhoneTrash()')}<main class="v454-phone-body">${phoneIdentityMarkup()}${rows.length?`<div class="v454-select-list">${rows.map(message=>`<label class="v454-select-row"><input type="checkbox" onchange="v454SelectPhoneMessage(${A(message.id)},this.checked)"><span><b>${E(messageText(message).slice(0,90)||'空消息')}</b><small>${E(message.worldTimeText||message.createdAt||'')}</small></span><time>${message.direction==='incoming'?'收到':'发出'}</time></label>`).join('')}</div>`:'<div class="vphone-empty">当前会话没有可管理的消息。</div>'}<div class="v454-section-title" style="color:#62686e"><span>删除语义</span><small>每次选择</small></div><label class="v454-radio-card"><input type="radio" name="v454DeleteMode" value="silent" ${phoneDeleteMode==='silent'?'checked':''} onchange="v454SetPhoneDeleteMode('silent')"><span><b>静默删除</b><small>只改本机；角色不能凭空知道。</small></span></label><label class="v454-radio-card"><input type="radio" name="v454DeleteMode" value="plot" ${phoneDeleteMode==='plot'?'checked':''} onchange="v454SetPhoneDeleteMode('plot')"><span><b>剧情删除</b><small>写入相关参与者记忆与手机事件时间线。</small></span></label><div class="v454-light-actions"><button class="red" onclick="v454DeleteSelectedPhoneMessages()">删除所选</button><button onclick="v454ClearPhoneMessagesApp()">清空聊天应用</button></div><section class="v454-light-panel" style="margin-top:10px"><h3>整部手机重置</h3><p>可只清内容并保留联系人、白名单、外观和设置；也可连本机设置一起重置。</p><div class="v454-light-actions"><button onclick="v454OpenPhoneReset()">查看重置边界</button></div></section></main></section></div>`)}
  function selectPhoneMessage(id,selected){if(selected)phoneSelectedIds.add(id);else phoneSelectedIds.delete(id)}
  function setPhoneDeleteMode(mode){phoneDeleteMode=mode==='plot'?'plot':'silent'}
  function trashMessage(thread,message,index,semantics){const store=currentPhoneStore(),entry={id:uid('phone_trash'),kind:'message',snapshot:clone(message),original:{app:'messages',threadId:thread.id,index},deleteSemantics:semantics,deletedAt:NOW(),expiresAt:store.phoneSettings.trashRetention==='permanent'?'':new Date(Date.now()+Math.max(1,Number(store.phoneSettings.trashRetention)||30)*86400000).toISOString()};store.trash.push(entry);return entry}
  function deleteSelectedPhoneMessages(){const thread=phoneThread();if(!thread)return toast('请先进入一条会话');if(!safePhonePermission('edit'))return toast('本次连接没有删除权限');if(!phoneSelectedIds.size)return toast('请先选择消息');const indexes=[];thread.messages.forEach((message,index)=>{if(phoneSelectedIds.has(message.id)){trashMessage(thread,message,index,phoneDeleteMode);indexes.push(index)}});thread.messages=thread.messages.filter(message=>!phoneSelectedIds.has(message.id));recordPhoneEvent({phoneOwner:activePhoneOwner,operation:'message-delete',localChanged:true,remoteSynced:false,deleteSemantics:phoneDeleteMode,remember:phoneDeleteMode==='plot',details:{summary:`从${thread.title}本机记录删除 ${indexes.length} 条消息`}});save();phoneSelectedIds.clear();openPhoneMessageManager();toast('已移入当前手机回收站；远端记录不变')}
  function deleteSinglePhoneMessage(messageId){activePhoneMessageId=messageId;phoneOverlay(`<header><div><small>删除语义</small><h2>选择删除语义</h2></div><button onclick="v454ClosePhoneOverlay()">×</button></header><div class="v454-phone-overlay-list"><button onclick="v454ConfirmSinglePhoneDelete('silent')"><b>静默删除</b><small>只删除本机副本，不进入角色记忆</small></button><button class="danger" onclick="v454ConfirmSinglePhoneDelete('plot')"><b>剧情删除</b><small>删除事件进入相关参与者记忆</small></button></div>`)}
  function confirmSinglePhoneDelete(semantics){const thread=phoneThread(),index=thread?.messages.findIndex(item=>item.id===activePhoneMessageId)??-1;if(!thread||index<0)return;if(!safePhonePermission('edit'))return toast('本次连接没有删除权限');const [message]=thread.messages.splice(index,1);trashMessage(thread,message,index,semantics);recordPhoneEvent({phoneOwner:activePhoneOwner,operation:'message-delete',localChanged:true,remoteSynced:false,deleteSemantics:semantics,remember:semantics==='plot',details:{summary:`从${thread.title}本机记录删除一条消息`}});save();closePhoneOverlay();openPhoneThread(thread.id);toast('已移入回收站；远端记录不变')}
  function clearPhoneMessagesApp(){if(!safePhonePermission('edit'))return toast('本次连接没有删除权限');if(!confirm('清空当前手机的聊天应用？内容会进入这部手机自己的回收站，其他应用和另一部手机不受影响。'))return;const store=currentPhoneStore();for(const thread of store.conversations)store.trash.push({id:uid('phone_trash'),kind:'conversation',snapshot:clone(thread),original:{app:'messages',index:store.conversations.indexOf(thread)},deleteSemantics:phoneDeleteMode,deletedAt:NOW(),expiresAt:store.phoneSettings.trashRetention==='permanent'?'':new Date(Date.now()+Math.max(1,Number(store.phoneSettings.trashRetention)||30)*86400000).toISOString()});const count=store.conversations.length;store.conversations=[];activePhoneThreadId='';recordPhoneEvent({phoneOwner:activePhoneOwner,operation:'app-clear',localChanged:true,remoteSynced:false,deleteSemantics:phoneDeleteMode,remember:phoneDeleteMode==='plot',details:{summary:`清空聊天应用，共 ${count} 条会话`}});save();openPhoneMessageManager();toast('聊天应用已清空并移入回收站')}
  function openPhoneTrash(){const store=currentPhoneStore(),items=store.trash.slice().reverse();setPhoneContent(`<div class="vphone v454-messages-shell ${activePhoneOwner==='user'?'is-user':'is-character'}"><section class="v454-phone-page" data-phone-route="trash">${phoneHead('回收站','v454OpenPhoneMessageManager()','设置','v454OpenTrashSettings()')}<main class="v454-phone-body">${phoneIdentityMarkup()}<section class="v454-light-panel"><h3>当前手机独立回收站</h3><p>默认保留 30 天，可切换永久保留；恢复时回到原应用和原位置。</p></section>${items.length?`<div class="v454-phone-list">${items.map(item=>`<article><span class="v454-phone-avatar">⌁</span><span><b>${E(item.kind==='conversation'?item.snapshot?.title:'已删除的本机消息')}</b><small>${E(item.kind==='conversation'?'来源：聊天应用':S(item.snapshot?.localText||item.snapshot?.text).slice(0,90))}</small></span><time><button onclick="v454RestoreTrashItem(${A(item.id)})" style="height:28px;padding:0 8px;border-radius:8px;background:#1c2024;color:#fff;font-size:6px">恢复</button></time></article>`).join('')}</div>`:'<div class="vphone-empty" style="margin-top:9px">回收站为空。</div>'}<div class="v454-light-actions"><button class="red" onclick="v454EmptyPhoneTrash()">清空回收站</button></div></main></section></div>`)}
  function restoreTrashItem(id){const store=currentPhoneStore(),index=store.trash.findIndex(item=>item.id===id),entry=store.trash[index];if(!entry)return;if(entry.kind==='conversation'){const at=Math.min(store.conversations.length,Math.max(0,Number(entry.original?.index)||0));store.conversations.splice(at,0,entry.snapshot)}else{let thread=store.conversations.find(item=>item.id===entry.original?.threadId);if(!thread){thread={id:S(entry.original?.threadId||uid('phone_thread')),title:'恢复的会话',kind:'direct',messages:[],createdAt:NOW(),updatedAt:NOW()};store.conversations.push(thread)}const at=Math.min(thread.messages.length,Math.max(0,Number(entry.original?.index)||0));thread.messages.splice(at,0,entry.snapshot)}store.trash.splice(index,1);save();openPhoneTrash();toast('已恢复到原应用和原位置')}
  function emptyPhoneTrash(){if(!confirm('永久清空当前这部手机的回收站？清空后无法恢复。'))return;currentPhoneStore().trash=[];save();openPhoneTrash();toast('当前手机回收站已清空')}
  function openTrashSettings(){const store=currentPhoneStore(),value=S(store.phoneSettings.trashRetention||30);phoneOverlay(`<header><div><small>回收站保留</small><h2>回收站保留时间</h2></div><button onclick="v454ClosePhoneOverlay()">×</button></header><div class="v454-phone-overlay-list"><button onclick="v454SetTrashRetention('30')"><b>保留 30 天</b><small>${value==='30'||value===30?'当前设置':''}</small></button><button onclick="v454SetTrashRetention('permanent')"><b>永久保留</b><small>${value==='permanent'?'当前设置':''}</small></button></div>`)}
  function setTrashRetention(value){currentPhoneStore().phoneSettings.trashRetention=value==='permanent'?'permanent':30;save();closePhoneOverlay();openPhoneTrash();toast('回收站保留时间已保存')}
  function openPhoneReset(){setPhoneContent(`<div class="vphone v454-messages-shell ${activePhoneOwner==='user'?'is-user':'is-character'}"><section class="v454-phone-page" data-phone-route="reset">${phoneHead('重置整部手机','v454OpenPhoneMessageManager()','取消','v454OpenPhoneMessageManager()')}<main class="v454-phone-body">${phoneIdentityMarkup()}<label class="v454-radio-card"><input type="radio" name="v454ResetMode" value="content" checked><span><b>只清内容</b><small>保留联系人、白名单、外观与设置。</small></span></label><label class="v454-radio-card"><input type="radio" name="v454ResetMode" value="all"><span><b>内容与本机设置一起重置</b><small>清空内容、联系人、白名单和本机设置。</small></span></label><section class="v454-light-panel" style="margin-top:10px"><h3>绝不会删除</h3><p>普通聊天、角色、USER 面具、世界书、记忆、另一部手机。</p></section><div class="v454-light-actions"><button class="red" onclick="v454ConfirmPhoneReset()">确认精确范围并重置</button></div></main></section></div>`)}
  function confirmPhoneReset(){if(!safePhonePermission('edit'))return toast('本次连接没有重置权限');const mode=document.querySelector('input[name="v454ResetMode"]:checked')?.value||'content';if(!confirm(`确认重置当前这部手机？${mode==='content'?'只清内容，保留联系人与设置。':'同时清空联系人、白名单与设置。'}普通聊天、角色、记忆和另一部手机绝不会删除。`))return;const store=currentPhoneStore();store.items=[];store.timeline=[];store.conversations=[];store.trash=[];if(mode==='all'){store.contacts=[];store.whitelist=[];store.phoneSettings={trashRetention:30,wallpaper:'',appearance:'dark'}}activePhoneThreadId='';recordPhoneEvent({phoneOwner:activePhoneOwner,operation:'phone-reset',localChanged:true,remoteSynced:false,deleteSemantics:'reset',remember:true,details:{summary:mode==='all'?'重置手机内容与本机设置':'只重置手机内容'}});save();openPhoneMessages();toast('当前手机已按选择范围重置')}
  window.v454OpenPhoneTools=openPhoneTools;window.v454OpenPhoneMessageManager=openPhoneMessageManager;window.v454SelectPhoneMessage=selectPhoneMessage;window.v454SetPhoneDeleteMode=setPhoneDeleteMode;window.v454DeleteSelectedPhoneMessages=deleteSelectedPhoneMessages;window.v454DeleteSinglePhoneMessage=deleteSinglePhoneMessage;window.v454ConfirmSinglePhoneDelete=confirmSinglePhoneDelete;window.v454ClearPhoneMessagesApp=clearPhoneMessagesApp;window.v454OpenPhoneTrash=openPhoneTrash;window.v454RestoreTrashItem=restoreTrashItem;window.v454EmptyPhoneTrash=emptyPhoneTrash;window.v454OpenTrashSettings=openTrashSettings;window.v454SetTrashRetention=setTrashRetention;window.v454OpenPhoneReset=openPhoneReset;window.v454ConfirmPhoneReset=confirmPhoneReset;

  function allContactRows(){const store=currentPhoneStore(),formal=phoneCandidates(activePhoneOwner),temporary=store.contacts.filter(item=>item.temporary===true).map(item=>({token:`temporary:${item.id}`,kind:'temporary',id:item.id,name:item.name||'临时 NPC',image:item.image||'',formal:false,description:item.description||''}));return[...formal,...temporary]}
  function openPhoneContacts(){const store=currentPhoneStore(),rows=allContactRows();setPhoneContent(`<div class="vphone v454-messages-shell ${activePhoneOwner==='user'?'is-user':'is-character'}"><section class="v454-phone-page" data-phone-route="contacts">${phoneHead('联系人白名单','v454OpenPhoneTools()','临时 NPC','v454NewTemporaryContact()')}<main class="v454-phone-body">${phoneIdentityMarkup()}<section class="v454-light-panel"><h3>联系人候选边界</h3><p>只来自当前世界绑定对象、当前 USER 面具关系、正式角色 / MPC 与已有正式群聊，再由 USER 白名单决定能否联系。</p></section>${rows.length?`<div class="v454-phone-list">${rows.map(row=>{const on=store.whitelist.includes(row.token),thread=store.conversations.find(item=>item.contactToken===row.token);return`<article>${threadAvatar({title:row.name,contactToken:row.token})}<span><b>${E(row.name)}</b><small>${row.formal?(row.kind==='group'?'已有正式群聊':row.kind==='mpc'?'正式 MPC':'当前世界角色'):'临时 NPC · 未转为正式 MPC'}</small></span><time style="display:flex;flex-direction:column;gap:4px"><button onclick="v454TogglePhoneWhitelist(${A(row.token)})" style="height:26px;padding:0 7px;border-radius:8px;background:${on?'#1c2024':'#f1f2f3'};color:${on?'#fff':'#41464c'};font-size:6px">${on?'白名单内':'加入'}</button>${on?`<button onclick="v454StartPhoneConversation(${A(row.token)})" style="height:26px;padding:0 7px;border-radius:8px;background:#f1f2f3;color:#41464c;font-size:6px">${thread?'打开会话':'新建会话'}</button>`:''}${!row.formal?`<button onclick="v454ConvertTemporaryContact(${A(row.id)})" style="height:26px;padding:0 7px;border-radius:8px;background:#f1f2f3;color:#41464c;font-size:6px">转 MPC</button>`:''}</time></article>`}).join('')}</div>`:'<div class="vphone-empty" style="margin-top:9px">当前世界和 USER 面具关系中还没有联系人候选。</div>'}<div class="v454-route-note" style="color:#62686e;background:#f7f8f9;border-color:#dfe2e5">主动说话必须已经存在会话，并为该联系人单独开启；第一阶段不支持任意临时建群。</div></main></section></div>`)}
  function togglePhoneWhitelist(token){const store=currentPhoneStore(),index=store.whitelist.indexOf(token);if(index>=0)store.whitelist.splice(index,1);else store.whitelist.push(token);save();openPhoneContacts()}
  function startPhoneConversation(token){const store=currentPhoneStore();if(!store.whitelist.includes(token))return toast('请先加入白名单');let thread=store.conversations.find(item=>item.contactToken===token);if(!thread){const row=allContactRows().find(item=>item.token===token);if(!row)return;thread={id:uid('phone_thread'),title:row.name,kind:row.kind==='group'?'group':'direct',contactToken:row.token,contactId:row.id,pinned:false,unread:0,proactiveEnabled:false,createdAt:NOW(),updatedAt:NOW(),messages:[]};store.conversations.push(thread);save()}activePhoneThreadId=thread.id;openPhoneThread(thread.id)}
